import React from 'react'

export interface LogoProps {
  variant?: 'full' | 'icon'
  size?: 'sm' | 'md' | 'lg' | 'xl'
  className?: string
  onClick?: () => void
}

// Official SUKAHALAL Logo embedded as base64 data URI (never 404s, renders instantly everywhere)
export const SUKAHALAL_LOGO_FULL = 'data:image/png;base64,'
export const SUKAHALAL_LOGO_ICON = 'data:image/png;base64,'

export default function Logo({
  variant = 'full',
  size = 'md',
  className = '',
  onClick,
}: LogoProps) {
  const fullHeights = {
    sm: 'h-8 max-h-8',
    md: 'h-10 max-h-10',
    lg: 'h-14 max-h-14',
    xl: 'h-20 max-h-20',
  }

  const iconSizes = {
    sm: 'w-8 h-8',
    md: 'w-10 h-10',
    lg: 'w-14 h-14',
    xl: 'w-20 h-20',
  }

  const isIconOnly = variant === 'icon'
  const src = isIconOnly ? SUKAHALAL_LOGO_ICON : SUKAHALAL_LOGO_FULL
  const sizeClass = isIconOnly ? iconSizes[size] : fullHeights[size]

  return (
    <div
      className={`inline-flex items-center cursor-pointer select-none transition-transform active:scale-95 hover:opacity-95 ${className}`}
      onClick={onClick}
      title="SUKAHALAL - Halal Supply Chain Ecosystem"
    >
      <img
        src={src}
        alt="SUKAHALAL Logo"
        className={`${sizeClass} w-auto object-contain drop-shadow-xs`}
        loading="eager"
      />
    </div>
  )
}
